mapper.update:
update orders
set order_status = #{status},
    updated_at = now()

    , pay_at = now()
    , pay_type = #{payType}


    , confirm_at = now()


    , ship_at = now(), courier = #{courier}, tracking_number = #{trackingNumber}


    , finish_at = now(), sign_status = 'signed'

where id = #{id} and shop_id = #{shopId}
